from frame import *

def upload_pill():
    return f'<div style="display: flex; align-items: center; gap: 8px; padding: 8px 8px 8px 20px; border-radius: 999px; background: {T["s1"]}; border: 2px solid {OL}; box-shadow: 4px 4px 0 {OL}; max-width: 520px; {A("up",.3)}">{icon("upload",20,T["mu"])}<span style="flex-grow: 1; font-size: 15px; color: {T["mu"]}">Drop a video you own, or choose a file</span>{btn("Get clips","primary",None,"SignUp.dc.html",arrow=True)}</div>'
def phone_fan(scale=1.0):
    ps = [('#9B7BFF','5 MONEY MYTHS',-14,1,'#FFD43B','ig',None,0),('#59D8FF','WAIT FOR IT',-6,3,'#FF4FB8',None,'98',1),('#FFD43B','I TRIED IT FOR A WEEK',0,2,'#2F5BFF','yt','99',2),('#FF7A2F','DON’T DO THIS',6,0,'#B6F24A',None,None,0),('#B6F24A','THE 50/30/20 RULE',14,4,'#FF4FB8','tt','100',1)]
    out = ''
    for i, (bg, cap, rot, skin, shirt, pl, sc, sty) in enumerate(ps):
        ml = '-36px' if i else '0'
        z = 5 - abs(i - 2)
        out += f'<div style="margin-left: {ml}; z-index: {z}; margin-top: {abs(i-2)*28}px; {A("up", .15+.08*i)}">{phone_html(vid_svg(bg, cap, skin, shirt, sc, pl, sty), rot, int(200*scale), .4*i)}</div>'
    return f'<div style="position: relative; display: flex; justify-content: center; align-items: flex-start; padding: 30px 0">{lime_blob(560, None, "left: 50%; top: 50%; transform: translate(-50%,-50%)")}<div style="position: relative; display: flex; align-items: flex-start">{out}</div><div style="position: absolute; top: 10px; left: 8%">{sticker("Nelio AI picked this","#FF4FB8",-6,"spark",15)}</div><div style="position: absolute; bottom: 30px; right: 6%">{sticker("Licensed ✓","#59D8FF",5,None,15,True,.6)}</div></div>'

def home():
    CUR['page']='public'; CUR['row']='M-01'
    hero = section(f'<div style="display: flex; flex-direction: column; align-items: center; text-align: center; gap: 22px">{sticker("Your AI content team","#FFD43B",-3,"spark",14)}{big("Turn one long video into " + hl("a week of shorts.") , 76, anim=A("up",.1))}{P("Nelio’s agents find the best moments, cut, caption and schedule them, only from content you own or have licensed, and only with the approvals and budgets you set.", size=19, anim=A("up",.2))}{upload_pill()}{small("Free plan forever · 3-day trial, no card needed")}</div>' + phone_fan(), pad='64px 48px 24px')
    logos = section(f'<div style="display: flex; flex-direction: column; align-items: center; gap: 18px">{h3("Built for the people who post every day", 20)}{P("Podcasters, streamers, small businesses and agencies across Nigeria and beyond.")}<div style="display: flex; gap: 14px; flex-wrap: wrap; justify-content: center">' + ''.join(f'<div style="position: relative; {A("pop", .06*i)}"><svg viewBox="0 0 100 100" width="72" height="72" aria-hidden="true"><circle cx="50" cy="50" r="48" fill="{c}" stroke="{OL}" stroke-width="3"></circle>{IL.person(50, 58, 0.9, i, "#2B1A10", s, i)}</svg><span style="position: absolute; right: -4px; bottom: -2px">{plat(p, 24)}</span></div>' for i, (c, s, p) in enumerate([('#FFD43B','#2F5BFF','yt'),('#59D8FF','#FF4FB8','ig'),('#FF4FB8','#FFD43B','tt'),('#B6F24A','#FF7A2F','ig'),('#FF7A2F','#59D8FF','yt'),('#9B7BFF','#B6F24A','ig'),('#FFD43B','#FF4FB8','yt')])) + '</div></div>', pad='40px 48px')
    def frow(eb, title, text, visual, flip=False, bg='#2F5BFF'):
        vis = f'<div style="flex: 1 1 480px; min-height: 340px; border-radius: 36px; background: {bg}; display: flex; align-items: center; justify-content: center; gap: 0; padding: 32px; position: relative; overflow: hidden; {A("up",.1)}">{visual}</div>'
        txt = f'<div style="flex: 1 1 380px; display: flex; flex-direction: column; gap: 14px; {A("up")}">{eyebrow(eb)}{H(title, 40)}{P(text, size=16)}<div>{btn("See how","secondary",None,"Product.dc.html",arrow=False)}</div></div>'
        return f'<div style="display: flex; flex-wrap: wrap; gap: 48px; align-items: center; {"flex-direction: row-reverse;" if flip else ""}">{txt}{vis}</div>'
    phones3 = ''.join(f'<div style="margin-left: {"-20px" if i else "0"}">{phone_html(vid_svg(c, cap, i+1, s, sc, pl, i), r, 170, .5*i)}</div>' for i, (c, cap, s, sc, pl, r) in enumerate([('#FFD43B','THE TRUTH','#FF4FB8','98','tt',-6),('#59D8FF','WAIT…','#2F5BFF','99','yt',0),('#FF4FB8','NO WAY','#B6F24A','100','ig',6)]))
    edit = f'<div style="background: #FFFFFF; border: 2px solid {OL}; border-radius: 26px; padding: 16px; width: 360px; display: flex; flex-direction: column; gap: 12px">{row(agent("pink","blob",34), small("Edit with words", OL, 800), gap=8)}<div style="padding: 12px 14px; border-radius: 16px; background: #F1F3F9; font-size: 14px; color: {OL}">Cut the first pause and make captions bigger</div>{row(chip("Done in 4 s","ok","check"), chip("≈2 credits","lime","zap"), gap=6)}</div>'
    caps = f'<div style="display: flex; gap: 10px">' + ''.join(f'<span style="padding: 10px 14px; border-radius: 14px; background: {b}; color: {OL}; border: 2px solid {OL}; font-family: {HF}; font-weight: 800; font-size: {fs}px; {A("pop",.1*i)}">{t}</span>' for i, (t, b, fs) in enumerate([('BOLD POP','#FFD43B',18),('minimal','#FFFFFF',16),('KARAOKE','#B6F24A',18)])) + '</div>'
    feats = section(sec_head('All-in-one studio', 'Everything you need to post every day.', 'One studio for clipping, captions, planning, approvals and publishing, with no editing skills needed.') +
        frow('Find the moments', 'The best 40 seconds, found for you.', 'Upload a podcast or stream. Nelio AI reads the transcript and scenes, ranks the moments most likely to work as shorts, and reframes them to 9:16. Scores are estimates. You always pick.', phones3) +
        frow('Edit with words', 'Tell it what to change. Done.', 'No timeline wrestling. Type “make captions bigger” or “cut the intro” and watch it happen. Full timeline editing is there when you want it.', edit, True, '#B6F24A') +
        frow('Captions that pop', 'Bold captions in your brand.', 'Animated captions in your fonts and colours, saved as a brand kit so every agent uses them.', caps, False, '#FF4FB8'))
    def scard(bg, title, text, illn):
        return f'<a href="Product.dc.html" style="text-decoration: none; color: {OL}; flex: 1 1 300px; border-radius: 32px; background: {bg}; border: 2px solid {OL}; box-shadow: 6px 6px 0 {OL}; padding: 24px; display: flex; flex-direction: column; gap: 10px; {A("up")}">{art(illn, 220)}<span style="font-family: {HF}; font-weight: 800; font-size: 22px">{e(title)}</span><span style="font-size: 14px; line-height: 1.5">{e(text)}</span><span style="display: inline-flex; align-items: center; gap: 8px; font-weight: 800; font-size: 14px">Explore {arrow_circle(OL, "#FFFFFF", 28)}</span></a>'
    convert = section(sec_head('Turn anything into shorts', 'Long video in. Scroll-stoppers out.') + f'<div style="display: flex; gap: 22px; flex-wrap: wrap">{scard("#FFD43B","Podcast → Shorts","Hour-long episodes become a week of clips.","media")}{scard("#59D8FF","Stream → Reels","Catch the hype moments from every stream.","exports")}{scard("#FF4FB8","Webinar → Clips","Turn talks into bite-size lessons.","strategist")}</div>', bg=T['s2'])
    def stepc(n, title, text, mock, d):
        return f'<div style="flex: 1 1 320px; display: flex; flex-direction: column; gap: 14px; {A("up", d)}"><div style="height: 200px; border-radius: 28px; background: {T["s2"]}; border: 1px solid {T["bd"]}; display: flex; align-items: center; justify-content: center; padding: 20px">{mock}</div>{eyebrow("Step " + n)}{h3(title, 22)}{P(text)}</div>'
    stepsec = section(sec_head('Seamless workflow', 'From upload to posted in 3 steps.') + f'<div style="display: flex; gap: 28px; flex-wrap: wrap">' +
        stepc('1', 'Upload or import', 'Drop a video you own, or pick something from a creator who licensed it to you.', upload_pill().replace("max-width: 520px","max-width: 300px"), 0) +
        stepc('2', 'Nelio AI does the work', 'Transcribe, find the moments, reframe, caption. You see the cost before it starts.', row(agent("pink","blob",56), col(chip("Transcribing…","blue","refresh"), chip("4 moments found","ai","spark"), chip("≈22 credits","lime","zap"), gap=6), gap=14), .1) +
        stepc('3', 'Approve & publish', 'Approve each platform, schedule, and Nelio posts it. Clients can approve from their phone.', row(plat("ig",40), plat("yt",40), f'<span style="--r: -8deg; padding: 8px 14px; border-radius: 14px; border: 3px solid #0E6F38; color: #0E6F38; font-family: {HF}; font-weight: 800; transform: rotate(-8deg); {A("stamp",.4)}">APPROVED</span>', gap=12), .2) + '</div>')
    trust = section(f'<div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 0; border-radius: 36px; background: {T["lime"]}; padding: 40px; position: relative; overflow: hidden">' + ''.join(f'<div style="padding: 10px 24px; {"border-left: 2px solid rgba(11,11,20,0.2);" if i else ""} display: flex; flex-direction: column; gap: 6px; color: {OL}">{icon(ic,30,OL,2.4)}<span style="font-family: {HF}; font-weight: 800; font-size: 28px; letter-spacing: -0.03em">{t}</span><span style="font-size: 15px">{s}</span></div>' for i, (ic, t, s) in enumerate([('check','Every post approved','Nothing publishes without the OK you set.'),('shield','Every source licensed','Your uploads or verified licenses only.'),('wallet','Every credit shown','Estimate before, actual after, hard limits.')])) + '</div>', pad='24px 48px')
    love = section(sec_head('Wall of love', 'Creators say it best.', 'Real quotes from our private beta will live here.') + f'<div style="display: flex; gap: 16px; flex-wrap: wrap; justify-content: center">' + ''.join(f'<div style="flex: 0 1 220px; border-radius: 28px; overflow: hidden; border: 2px solid {OL}; background: {c}; position: relative; height: 300px"><svg viewBox="0 0 220 300" aria-hidden="true" style="position: absolute; inset: 0; width: 100%; height: 100%">{IL.person(110, 210, 2.2, i, "#2B1A10", s, i)}</svg><div style="position: absolute; left: 12px; right: 12px; bottom: 12px; padding: 10px 12px; border-radius: 16px; background: #FFFFFF; border: 2px solid {OL}; font-size: 13px; font-weight: 600; color: {OL}">[Beta creator quote]<br><span style="color: #5B6175">[Name] · [Niche]</span></div></div>' for i, (c, s) in enumerate([('#59D8FF','#FFD43B'),('#FFD43B','#FF4FB8'),('#FF4FB8','#2F5BFF'),('#B6F24A','#FF7A2F'),('#FF7A2F','#59D8FF')])) + '</div>')
    pricing = section(sec_head('Flexible plans', 'Scale your content, not your budget.') + row(btn('See all plans','cta',None,'Pricing.dc.html',arrow=True), justify='center'), bg=T['s2'])
    cta = section(f'<div style="border-radius: 40px; background: {T["acc"]}; padding: 64px 48px; display: flex; flex-direction: column; align-items: center; gap: 20px; text-align: center; position: relative; overflow: hidden">{lime_blob(300, "#3D63FF", "left: -60px; top: -80px")}{lime_blob(260, "#3D63FF", "right: -40px; bottom: -90px")}<div style="position: relative; display: flex; flex-direction: column; align-items: center; gap: 18px">{sticker("Free forever plan","#FFD43B",-4)}{big("Ready to meet your agents?", 60, "#FFFFFF")}{P("Start free. Upgrade when your agents are pulling their weight.", "#FFFFFF", 18)}{btn("Start free","cta",None,"SignUp.dc.html","lg",arrow=True)}</div></div>', pad='40px 48px 80px')
    pub_page('Home.dc.html', 'M-01 Home', hero + logos + feats + convert + stepsec + trust + love + pricing + cta, h=6200)

    # M-02 Product
    CUR['row']='M-02'
    prod = section(f'<div style="display: flex; flex-direction: column; align-items: center; text-align: center; gap: 18px">{sticker("Product tour","#B6F24A",-3)}{big("How Nelio works", 72)}{tabs(["Agents","Clipping","Content Studio","Approvals","Licensing","Analytics"], 1)}</div>', pad='64px 48px 24px')
    prod += section(f'<div style="display: flex; flex-wrap: wrap; gap: 40px; align-items: center"><div style="flex: 1 1 520px; border-radius: 36px; background: #2F5BFF; padding: 28px">{card(wide_video(), row(chip("“Stop budgeting like this”","lime"), chip("score 82 · estimate","neutral"), chip("0:12–0:54","neutral")), pad=16)}</div><div style="flex: 1 1 400px; display: flex; flex-direction: column; gap: 16px">{eyebrow("Clipping")}{H("Find the 40 seconds that matter", 44)}{P("Nelio AI reads the transcript and scenes, ranks the moments, and you pick. Scores are estimates, never promises.", size=17)}{lst([("Transcribe","Fast, Balanced or High Quality", bubble("type","blue",40)),("Detect scenes","Clean cuts at natural breaks", bubble("film","ai",40)),("Reframe to 9:16","Keeps the speaker in frame", bubble("phone","lime",40)),("Caption with your brand","Your fonts and colours", bubble("palette","warn",40))])}</div></div>')
    prod += section(f'<div style="display: flex; gap: 22px; flex-wrap: wrap">' + ''.join(f'<div style="flex: 1 1 300px; border-radius: 32px; background: {b}; border: 2px solid {OL}; box-shadow: 6px 6px 0 {OL}; padding: 24px; display: flex; flex-direction: column; gap: 10px; color: {OL}">{art(il, 200)}<span style="font-family: {HF}; font-weight: 800; font-size: 22px">{t}</span><span style="font-size: 14px">{s}</span>{x}</div>' for b, il, t, s, x in [('#FFD43B','strategist','Nelio AI plans and writes','Strategy, hooks, captions and research.',''),('#B6F24A','brand','Brand kits','Every agent uses your look.',''),('#59D8FF','aivideo','Original AI video','Needs a specialist video partner.', sticker('Coming later','#FFFFFF',-3,size=12))]) + '</div>', bg=T['s2'])
    pub_page('Product.dc.html', 'M-02 Product', prod, h=2700)

    # M-03 Use cases
    CUR['row']='M-03'
    uc = section(f'<div style="display: flex; flex-wrap: wrap; gap: 40px; align-items: center"><div style="flex: 1 1 520px; display: flex; flex-direction: column; gap: 20px">{tabs(["Creators","Businesses","Agencies"],2)}{big("Run every client " + hl("from one place"), 64)}{P("Separate client workspaces, client logins and per-platform approvals, with an audit trail for every decision.", size=19)}{row(btn("Start agency trial","cta",None,"SignUp.dc.html","lg",arrow=True), btn("Book a demo","secondary",size="lg"))}</div><div style="flex: 1 1 420px; position: relative; display: flex; justify-content: center">{art("clients", 440)}</div></div>', pad='64px 48px')
    uc += section(grid([card(bubble(ic, t, 52), h3(a, 20), P(b), pad=24) for ic, t, a, b in [('grid','blue','Client workspaces','Fully isolated accounts, content, licenses and spend.'),('check','warn','Client approval portal','Clients approve each platform from their phone.'),('users','ai','Team roles','Owners, admins, managers, editors, viewers, client approvers.'),('list','lime','Audit log','Who approved what, which revision, when.'),('wallet','ok','Spend limits per client','Work pauses instead of overspending.'),('chart','blue','Cross-client overview','What’s waiting on whom, across clients.')]], cols=3, minw=300), bg=T['s2'])
    pub_page('UseCases.dc.html', 'M-03 Use cases', uc, h=2100)

    # M-04 Pricing
    CUR['row']='M-04'
    def plan(name, price, blurb, feats, art_bg, shapes, hot=False, cta='Choose plan', href='SignUp.dc.html'):
        li = ''.join(f'<li style="display: flex; gap: 8px; font-size: 14px; align-items: flex-start; color: {T["tx"]}"><span style="width: 20px; height: 20px; border-radius: 50%; background: {T["acc"]}; display: inline-flex; align-items: center; justify-content: center; flex: none">{icon("check",12,"#FFFFFF",3)}</span><span>{e(f)}</span></li>' for f in feats)
        head = f'<div style="height: 120px; border-radius: 22px; background: {art_bg}; position: relative; overflow: hidden; border: 2px solid {OL}">{shapes}<span style="position: absolute; left: 14px; top: 14px; display: inline-flex; align-items: center; gap: 6px; padding: 4px 12px; border-radius: 999px; background: #FFFFFF; border: 2px solid {OL}; font-weight: 800; font-size: 13px; color: {OL}">{e(name)}</span></div>'
        tag = sticker('Most popular','#FFD43B',4,'star',12,False) if hot else ''
        return f'<section style="background: {T["s1"]}; border: {"3px solid "+T["acc"] if hot else "1px solid "+T["bd"]}; border-radius: 30px; padding: 14px; display: flex; flex-direction: column; gap: 14px; box-shadow: {T["shadow"]}; position: relative">{"<div style=\"position: absolute; top: -14px; right: 14px\">"+tag+"</div>" if hot else ""}{head}<div style="padding: 0 8px; display: flex; flex-direction: column; gap: 12px; flex-grow: 1"><div style="display: flex; align-items: baseline; gap: 4px"><span style="font-family: {HF}; font-weight: 800; font-size: 42px; letter-spacing: -0.03em">{e(price)}</span><span style="font-size: 14px; color: {T["mu"]}">{"/mo" if price.startswith("$") else ""}</span></div>{P(blurb)}<ul style="list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 8px; flex-grow: 1">{li}</ul>{btn(cta, "primary" if hot else "secondary", None, href, full=True)}</div></section>'
    sh = lambda c1, c2: f'<svg aria-hidden="true" viewBox="0 0 200 120" preserveAspectRatio="xMidYMid slice" style="position: absolute; inset: 0; width: 100%; height: 100%"><circle cx="160" cy="30" r="44" fill="{c1}" stroke="{OL}" stroke-width="3"></circle><rect x="40" y="70" width="90" height="90" rx="30" fill="{c2}" stroke="{OL}" stroke-width="3" transform="rotate(-18 85 115)"></rect></svg>'
    pr = section(f'<div style="display: flex; flex-direction: column; align-items: center; text-align: center; gap: 16px">{eyebrow("Flexible plans")}{big("Simple plans. Hard limits.", 68)}{P("Prices in USD. Pay in naira at checkout where supported. You’ll see the exact amount before you confirm.", size=18)}{tabs(["Monthly","Yearly · coming later"],0)}</div>', pad='64px 48px 24px')
    pr += section(grid([plan('Free','$0','Try Nelio by hand.',['1 agent, manual only','1 social account','Very limited credits','No autonomous publishing'],'#F1F3F9',sh('#FFFFFF','#E4E8F1'),cta='Start free'),
                        plan('Starter','$19','For getting consistent.',['2 agents','3 social accounts','Autonomous publishing','Top-ups'],'#59D8FF',sh('#FFD43B','#FFFFFF')),
                        plan('Creator Pro','$49','For full-time creators.',['5 agents','6 social accounts','Batch variants','Priority rendering'],'#2F5BFF',sh('#B6F24A','#FF4FB8'),hot=True),
                        plan('Business','$99','For small teams.',['10 agents','12 social accounts','Team seats','Approval workflows'],'#B6F24A',sh('#FFFFFF','#59D8FF')),
                        plan('Agency','$249','For client work.',['25 agents','40 social accounts','10 client workspaces','Client portal & audit log'],'#FF4FB8',sh('#FFD43B','#FFFFFF')),
                        plan('Enterprise','Custom','For big operations.',['Custom limits','SSO (planned)','Dedicated support'],'#FFD43B',sh('#FF7A2F','#FFFFFF'),cta='Talk to us')], cols=3, gap=18, minw=300) +
                   banner('blue','Plan limits and credit amounts are provisional','We are measuring real processing costs before launch. Final numbers will be shown here before you pay anything.') +
                   f'<div style="display: flex; flex-wrap: wrap; gap: 24px; align-items: center; border-radius: 32px; background: {T["s2"]}; padding: 24px 28px">{art("gift", 180)}<div style="flex: 1 1 360px; display: flex; flex-direction: column; gap: 6px">{H("3-day trial of paid features", 28)}{P("1 agent · 1 account · 2 short exports · a hard compute cap. No card needed, and you’re never charged automatically.", size=15)}</div>{btn("Start trial","cta",None,"SignUp.dc.html",arrow=True)}</div>', pad='24px 48px 80px')
    pub_page('Pricing.dc.html', 'M-04 Pricing', pr, h=2500)

    # M-05 Licensing
    CUR['row']='M-05'
    li = section(f'<div style="display: flex; flex-wrap: wrap; gap: 40px; align-items: center; position: relative"><div style="flex: 1 1 560px; display: flex; flex-direction: column; gap: 20px">{sticker("For content owners","#59D8FF",-3,"shield")}{big("Get clipped, " + hl("on your terms"), 68)}{P("Verify your channel, choose what people may do with your videos, see every use and revoke any time. Free, no subscription.", size=19)}{row(btn("Join free as a content owner","cta",None,"ContentOwnerJoin.dc.html","lg",arrow=True), btn("How licensing works","secondary",size="lg"))}</div><div style="flex: 1 1 380px; display: flex; justify-content: center">{art("licenses", 420)}</div></div>', pad='64px 48px')
    li += section(f'<div style="display: flex; gap: 20px; flex-wrap: wrap">' + ''.join(f'<div style="flex: 1 1 240px; border-radius: 30px; background: {b}; border: 2px solid {OL}; box-shadow: 5px 5px 0 {OL}; padding: 22px; display: flex; flex-direction: column; gap: 8px; color: {OL}">{icon(ic,30,OL,2.4)}<span style="font-family: {HF}; font-weight: 800; font-size: 20px">{t}</span><span style="font-size: 14px">{s}</span></div>' for b, ic, t, s in [('#B6F24A','shield','Verify ownership','Sign in with your platform to prove the channel is yours.'),('#FFD43B','file','Set allowed uses','Clips, compilations, platforms, attribution, expiry.'),('#59D8FF','eye','See every use','Every clip made from your videos, and where it went.'),('#FF4FB8','x','Revoke instantly','New use stops at once; published posts get flagged.')]) + '</div>', bg=T['s2'])
    li += section(grid([banner('blue','Paid licensing and payouts are coming later','We’ll open them once legal, tax and payment requirements are met.'), card(h3('What we never do'), lst([('Treat public videos as licensed',None,icon('x',18,T['errTx'])),('Assume silence means yes',None,icon('x',18,T['errTx'])),('Ignore third-party music or footage',None,icon('x',18,T['errTx']))]))], cols=2, minw=400))
    pub_page('Licensing.dc.html', 'M-05 Licensing & Creator Partners', li, h=2400)

    # M-06 FAQ
    CUR['row']='M-06'
    qa = [('Can Nelio post without me?','Only if you turn on autonomous publishing for a specific agent, account and budget, and confirm it. It’s off by default and not available on the Free plan.', True),('Which platforms work today?','YouTube and Instagram are in development. TikTok and Facebook are coming later. We switch each on only after the official integration is approved.', False),('How do credits work?','',False),('What happens when a license is revoked?','',False),('Do you guarantee views or monetization?','',False),('Can I pay in naira?','',False)]
    faq = ''.join(f'<details {"open" if o else ""} style="border: 1px solid {T["bd"]}; border-radius: 24px; background: {T["s1"]}; padding: 20px 24px; box-shadow: {T["shadow"]}; {A("up", .05*i)}"><summary style="cursor: pointer; font-family: {HF}; font-weight: 800; font-size: 18px; color: {T["tx"]}; display: flex; justify-content: space-between; gap: 12px">{e(q)}<span style="color: {T["accTx"]}">{"−" if o else "+"}</span></summary>{"<div style=\"margin-top: 10px\">"+P(a, size=15)+"</div>" if a else ""}</details>' for i, (q, a, o) in enumerate(qa))
    f_ = section(f'<div style="display: flex; flex-wrap: wrap; gap: 48px"><div style="flex: 1 1 360px; display: flex; flex-direction: column; gap: 16px">{eyebrow("FAQ")}{big("Everything you need to know.", 52)}{P("Can’t find your answer? Our support team is a message away.", size=16)}{art("search", 300)}</div><div style="flex: 2 1 560px; display: flex; flex-direction: column; gap: 12px">{tabs(["General","Licensing","Billing","Agencies","Platforms","Privacy"],0)}{faq}</div></div>', pad='64px 48px')
    pub_page('FAQ.dc.html', 'M-06 FAQ', f_, h=1900)

    # M-07 Legal
